  val arbiter_request_fact_Id : Art.PortId) extends Request_Qualifier_Api {

  // Logika spec var representing port state for incoming data port
  @spec var request: Factory_Dispatch_Coordinator.Raw_Dispatch_Request = $

  def get_request() : Option[Factory_Dispatch_Coordinator.Raw_Dispatch_Request] = {
    Contract(
      Ensures(
        Res == Some(request)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Raw_Dispatch_Request] = Art.getValue(request_Id) match {
